const std = @import("std");

/// A bounded reader for little-endian binary records. The cursor advances only
/// after a successful read. A record starts with a two-byte payload length,
/// followed by exactly that many bytes. The returned slice borrows the input;
/// callers must not free it separately. An incomplete record must leave the
/// cursor unchanged so that a caller can retry after obtaining more input.
const Reader = struct {
    bytes: []const u8,
    position: usize = 0,

    pub fn remaining(self: Reader) usize {
        return self.bytes.len - self.position;
    }

    pub fn readByte(self: *Reader) error{EndOfInput}!u8 {
        if (self.remaining() == 0) return error.EndOfInput;
        const value = self.bytes[self.position];
        self.position += 1;
        return value;
    }

    pub fn readRecord(self: *Reader) error{EndOfInput}![]const u8 {
        const start = self.position;
        if (self.remaining() < 2) return error.EndOfInput;
        const length = @as(usize, self.bytes[start]) |
            (@as(usize, self.bytes[start + 1]) << 8);
